// Автоматически сгенерировано из оригинальной библиотеки существ Lenia
// (Bert Wang-Chak Chan, github.com/Chakazul/Lenia, Python/animals.json).
// Клетки хранятся как base64 из байтов k (значение клетки = k / 255) — без потерь точности.
// Каждое существо проверено эталонной симуляцией (NumPy): выживает и сохраняет форму.
export interface Creature {
  id: string;
  name: string;
  ru: string;
  desc: string;
  kind: 'glider' | 'oscillator' | 'replicator' | 'rotator';
  kindRu: string;
  speed: number;
  R: number; T: number; b: number[]; m: number; s: number; kn: number; gn: number;
  w: number; h: number;
  /** base64 Uint8: значение клетки = байт / 255 */
  data: string;
  /** Декодированные клетки (row-major, row 0 = верх, значения 0..1). */
  cells: number[];
}

type CreatureData = Omit<Creature, 'cells'>;

