/** Декодирует base64-клетки в значения 0..1 (ровно k/255). */
function decodeAll(list: CreatureData[]): Creature[] {
  return list.map((c) => {
    const bin = atob(c.data);
    const cells = new Array<number>(bin.length);
    for (let i = 0; i < bin.length; i++) cells[i] = bin.charCodeAt(i) / 255;
    return { ...c, cells };
  });
}

export const CREATURES: Creature[] = decodeAll(DATA);

/** Виды для пруда блюдцев: помещаются в тор 96×96 (w+2R ≤ 96), проверены NumPy. */
